inputs += ['app/src/features/room/painting-controller.ts','app/src/features/room/environment-controller.ts','app/src/features/room/room-controls.tsx','app/src/features/experience/controller.ts','app/src/features/experience/interaction-registry.ts','app/src/features/experience/project-transition.ts','app/src/features/experience/audio.ts','app/src/features/character/greeting-controller.ts','app/src/features/monitor/launcher.tsx','app/tests/e2e/physical-interactions.spec.ts','app/tests/integration/runtime/frozen-world-binding.test.ts']
