models=[]
for name in ['production-room-full.glb','resident-production.glb','fixture-production.glb','interaction-assets.glb']:
 p=root/'app/public/models'/name; b=p.read_bytes(); j=json.loads(b[20:20+struct.unpack_from('<I',b,12)[0]]); inputs.append(str(p).replace('\\','/')); models.append({'path':str(p),'bytes':len(b),'nodes':len(j.get('nodes',[])),'meshes':len(j.get('meshes',[])),'animations':[{'name':a.get('name'),'channels':len(a['channels']),'targets':sorted(set(j['nodes'][c['target']['node']].get('name','') for c in a['channels']))} for a in j.get('animations',[])],'hexPanels':[n.get('name') for n in j.get('nodes',[]) if 'hex_panel' in n.get('name','')]})
(out/'asset-inspection.json').write_text(json.dumps(models,indent=2)+'\n')
(out/'input-hashes.json').write_text(json.dumps({p:hashlib.sha256(root.joinpath(p).read_bytes()).hexdigest() for p in inputs},indent=2)+'\n')
